#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gzip_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *inbuf = malloc(fsize);
    fread(inbuf, 1, fsize, f);
    fclose(f);

    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    int ret = inflateInit2(&strm, MAX_WBITS + 32);
    if (ret != Z_OK) {
        fprintf(stderr, "inflateInit2 failed: %d\n", ret);
        return 1;
    }

    strm.next_in = inbuf;
    strm.avail_in = fsize;

    // Use a 258-byte buffer (minimum for inflate_fast)
    unsigned char *outbuf = malloc(258);
    memset(outbuf, 0xAB, 258);

    strm.next_out = outbuf;
    strm.avail_out = 258;

    ret = inflate(&strm, Z_SYNC_FLUSH);
    printf("inflate returned: %d\n", ret);
    printf("avail_in: %u, avail_out: %u\n", strm.avail_in, strm.avail_out);
    printf("total_out: %lu\n", strm.total_out);
    printf("msg: %s\n", strm.msg ? strm.msg : "NULL");

    // Don't check for overflow here - just let ASAN catch it
    // The inflate call itself should trigger ASAN if it writes past the buffer

    inflateEnd(&strm);
    free(inbuf);
    free(outbuf);
    return 0;
}
EOF
